class GoogleSheetsImporter{constructor(e){this.listsManager=e,this.currentStep=1,this.totalSteps=5,this.googleSheetsUrl=null,this.spreadsheetId=null,this.sheetGid=null,this.fileContent=null,this.csvImporter=null,this.container=null}init(){this.container||(this.container=document.getElementById("import-wizard")),this.container?(this.renderStep1(),debugLog("[GoogleSheetsImporter] Initialized")):console.error("[GoogleSheetsImporter] Container not found")}renderStep1(){this.currentStep=1,this.container.innerHTML='\n            <div class="google-sheets-wizard-step">\n                <div class="mb-4">\n                    <div class="text-sm breadcrumbs">\n                        <ul>\n                            <li class="font-bold">Шаг 1: Ввод ссылки</li>\n                            <li class="opacity-50">Шаг 2: Анализ данных</li>\n                            <li class="opacity-50">Шаг 3: Сопоставление колонок</li>\n                            <li class="opacity-50">Шаг 4: Предпросмотр</li>\n                            <li class="opacity-50">Шаг 5: Импорт</li>\n                        </ul>\n                    </div>\n                </div>\n\n                <div class="alert alert-info mb-4">\n                    <svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">\n                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />\n                    </svg>\n                    <div>\n                        <p class="font-bold">Важно!</p>\n                        <p class="text-sm">Google Sheets должна быть публичной: <strong>"Доступ по ссылке → Просмотр для всех"</strong></p>\n                    </div>\n                </div>\n\n                <form onsubmit="window.googleSheetsImporter.handleUrlSubmit(event)">\n                    <div class="form-control mb-4">\n                        <label class="label">\n                            <span class="label-text font-medium">Ссылка на Google Sheets</span>\n                        </label>\n                        <input type="url"\n                               id="google-sheets-url-input"\n                               class="input input-bordered w-full"\n                               placeholder="https://docs.google.com/spreadsheets/d/1ABC.../edit#gid=0"\n                               required\n                               pattern=".*docs\\.google\\.com/spreadsheets.*">\n                        <label class="label">\n                            <span class="label-text-alt">Вставьте ссылку из адресной строки браузера</span>\n                        </label>\n                    </div>\n\n                    <div class="flex gap-2">\n                        <button type="button"\n                                class="btn btn-ghost"\n                                onclick="window.importManager.reset()">\n                            ← Назад к выбору метода\n                        </button>\n                        <button type="submit" class="btn btn-primary">\n                            🔍 Загрузить данные\n                        </button>\n                    </div>\n                </form>\n\n                <div class="mt-6 space-y-4">\n                    <details class="collapse collapse-arrow bg-base-200">\n                        <summary class="collapse-title font-medium">\n                            📖 Как получить ссылку\n                        </summary>\n                        <div class="collapse-content">\n                            <ol class="list-decimal list-inside space-y-2 text-sm">\n                                <li>Откройте Google Sheets в браузере</li>\n                                <li>Нажмите кнопку <strong>"Настройки доступа"</strong> (в правом верхнем углу)</li>\n                                <li>Выберите <strong>"Доступ по ссылке"</strong></li>\n                                <li>Установите <strong>"Просмотр для всех, у кого есть ссылка"</strong></li>\n                                <li>Нажмите <strong>"Готово"</strong></li>\n                                <li>Скопируйте ссылку из адресной строки браузера</li>\n                            </ol>\n                        </div>\n                    </details>\n\n                    <details class="collapse collapse-arrow bg-base-200">\n                        <summary class="collapse-title font-medium">\n                            📋 Формат данных\n                        </summary>\n                        <div class="collapse-content">\n                            <ul class="list-disc list-inside space-y-2 text-sm">\n                                <li><strong>Первая строка</strong> - заголовки колонок</li>\n                                <li><strong>Обязательные колонки:</strong> Магазин, Группа товаров, Товар</li>\n                                <li><strong>Опциональные:</strong> Количество, Единица, Комментарий</li>\n                                <li>Лист автоматически определяется из URL (параметр #gid)</li>\n                                <li>Если #gid не указан - будет использован первый лист</li>\n                            </ul>\n                        </div>\n                    </details>\n\n                    <details class="collapse collapse-arrow bg-base-200">\n                        <summary class="collapse-title font-medium">\n                            🛠️ Устранение неполадок\n                        </summary>\n                        <div class="collapse-content">\n                            <ul class="list-disc list-inside space-y-2 text-sm">\n                                <li><strong>"Таблица не публична"</strong> → Проверьте настройки доступа (шаг 2-4 выше)</li>\n                                <li><strong>"Таблица не найдена"</strong> → Проверьте правильность ссылки</li>\n                                <li><strong>"Неверный формат ссылки"</strong> → Используйте ссылку из адресной строки браузера</li>\n                                <li><strong>Нужен конкретный лист?</strong> → Откройте этот лист и скопируйте URL с #gid=...</li>\n                            </ul>\n                        </div>\n                    </details>\n                </div>\n            </div>\n        ',debugLog("[GoogleSheetsImporter] Rendered step 1")}async handleUrlSubmit(e){e.preventDefault();const t=document.getElementById("google-sheets-url-input");if(this.googleSheetsUrl=t.value.trim(),this.googleSheetsUrl)if(this.googleSheetsUrl.includes("docs.google.com/spreadsheets"))try{showToast("Загрузка данных из Google Sheets...","info"),debugLog("[GoogleSheetsImporter] Fetching Google Sheets:",this.googleSheetsUrl);const e=await fetch("/api/v1/shopping-lists/google-sheets/fetch",{method:"POST",headers:{"Content-Type":"application/json"},credentials:"same-origin",body:JSON.stringify({google_sheets_url:this.googleSheetsUrl})});if(!e.ok){const t=await e.json();let s;throw s=Array.isArray(t.detail)?t.detail.map((e=>e.msg||JSON.stringify(e))).join(", "):"string"==typeof t.detail?t.detail:t.detail?JSON.stringify(t.detail):`HTTP ${e.status}`,new Error(s)}const t=await e.json();this.fileContent=t.file_content,this.spreadsheetId=t.spreadsheet_id,this.sheetGid=t.sheet_gid,debugLog("[GoogleSheetsImporter] Fetched successfully:",{spreadsheetId:this.spreadsheetId,sheetGid:this.sheetGid,size:this.fileContent.length}),showToast("✅ Данные загружены из Google Sheets","success"),this.delegateToCSVImporter()}catch(e){console.error("[GoogleSheetsImporter] Error fetching Google Sheets:",e),showToast(`❌ Ошибка загрузки: ${e.message}`,"error")}else showToast("Неверный формат ссылки. Используйте ссылку на Google Sheets","error");else showToast("Введите ссылку на Google Sheets","error")}async delegateToCSVImporter(){if(!this.csvImporter){if("undefined"==typeof CSVImporter)return console.error("[GoogleSheetsImporter] CSVImporter not loaded"),void showToast("Ошибка: CSV импортер не загружен","error");this.csvImporter=new CSVImporter(this.listsManager),window.csvImporter=this.csvImporter,this.csvImporter.onBackToStep1="window.googleSheetsImporter.renderStep1()"}try{const e=decodeURIComponent(escape(atob(this.fileContent)));this.csvImporter.fileContent=e}catch(e){return console.error("[GoogleSheetsImporter] Error decoding base64:",e),void showToast("Ошибка декодирования данных","error")}this.csvImporter.container=this.container;try{await this.csvImporter.analyzeFile(),this.csvImporter.renderStep2()}catch(e){console.error("[GoogleSheetsImporter] Error analyzing CSV:",e),showToast(`Ошибка анализа: ${e.message}`,"error")}debugLog("[GoogleSheetsImporter] Delegated to CSVImporter")}escapeHtml(e){const t=document.createElement("div");return t.textContent=e,t.innerHTML}}window.GoogleSheetsImporter=GoogleSheetsImporter,debugLog("[GoogleSheetsImporter] Module loaded");